import collections
def components(g,val):
    H,W=len(g),len(g[0]); seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=val and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    x,y=st.pop()
                    if (x,y) in seen: continue
                    seen.add((x,y)); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and g[nx][ny]==val and (nx,ny) not in seen: st.append((nx,ny))
                comps.append(comp)
    return comps
