                x,y=r+dr,c+dc; a=0
                while 0<=x<H and 0<=y<W and g[x][y]==bg:
                    a+=1;x+=dr;y+=dc
                x2,y2=r-dr,c-dc; b=0
                while 0<=x2<H and 0<=y2<W and g[x2][y2]==bg:
                    b+=1;x2-=dr;y2-=dc
                if (0<=x<H and 0<=y<W) and (0<=x2<H and 0<=y2<W) and g[x][y]!=bg and g[x2][y2]!=bg and a+b<=K:
                    out[r][c]=2; break
    return out
for n in (3,4,5,6):
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    pred=solve(gi)
    dd=[(r,c,gi[r][c],pred[r][c],go[r][c]) for r in range(len(gi)) for c in range(len(gi[0])) if pred[r][c]!=go[r][c]]
    print(n,'match',pred==go,'ndiff',len(dd),dd[:8])
